//! Page composite (2026-10-28): pages with pictures, shapes, lines, text
//! boxes, empty sheets, and canvas pages whose Samsung picture cannot be
//! fetched/decoded are drawn locally instead of having no image.
//!
//! Synthetic data only: `tests/fixtures/objects_note.json` is generated by
//! `cargo test -p notes-host --test ink_objects -- --ignored
//! regen_preview_objects_fixture` (page 1: picture, two strokes, foreign
//! shape, odd line, text box; page 2: picture only plus a canvas-cache entry;
//! page 3: empty). The pictures are tiny synthetic PNGs; no network.
mod common;
use common::*;
use notes_preview::ink::{is_composite, prepare};
use notes_preview::manager::{Fetcher, PreviewOptions};
use notes_preview::{CanvasPreviewCandidate, Fail, PreviewEnv, PreviewManager, Val};
use std::collections::BTreeMap;
use std::sync::{Arc, Mutex};
use std::time::Duration;

fn fixture() -> (Val, BTreeMap<String, Vec<u8>>) {
    let text = std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/objects_note.json")).unwrap();
    let value = rs_store::val::loads(&text).unwrap();
    let Some(Val::Dict(images)) = value.get("images").cloned() else { panic!() };
    let images = images.into_iter().map(|(k, v)| (k, rs_editor::pyval::b64decode_strict(v.as_str().unwrap()).unwrap())).collect();
    (value.get("snapshot").unwrap().clone(), images)
}

/// A fake account transport serving the fixture's pictures by content hash
/// (and recording what was asked).
fn media(images: BTreeMap<String, Vec<u8>>, asked: Arc<Mutex<Vec<String>>>) -> Fetcher {
    Arc::new(move |c: &CanvasPreviewCandidate, _: &dyn PreviewEnv, _: &dyn Fn() -> Result<(), Fail>| {
        asked.lock().unwrap().push(c.sha256.clone());
        assert!(c.download_url.as_deref().is_some_and(|u| u.starts_with("https://ew1a-api.samsungcloud.com/")));
        images.get(&c.sha256).cloned().ok_or_else(|| Fail::new(notes_preview::Kind::Preview, "synthetic: not found"))
    })
}

fn manager_with(dir: &std::path::Path, env: Arc<TestEnv>, media: Option<Fetcher>, canvas: Option<Fetcher>) -> (Arc<PreviewManager>, String) {
    let s = store(dir);
    let (snapshot, _) = fixture();
    let existing = s.with_db(|db| {
        use rs_store::db::Sql;
        db.query("SELECT id FROM notes", &[])
    }).unwrap();
    let id = match existing.one() {
        Some(row) => row.text("id").unwrap().to_string(),
        None => note_with_document(&s, &snapshot),
    };
    let options = PreviewOptions { media_fetcher: media, fetcher: canvas, ..Default::default() };
    (Arc::new(PreviewManager::with_options(s, env, options).unwrap()), id)
}

fn pages(manifest: &Val) -> Vec<Val> {
    match manifest.get("pages") {
        Some(Val::List(p)) => p.clone(),
        _ => panic!(),
    }
}

fn wait_png(m: &PreviewManager, id: &str, index: i64) -> Vec<u8> {
    for _ in 0..3 {
        if let Some(png) = m.request(id, index, 0, 60.0).unwrap() {
            return png;
        }
    }
    panic!("page {index} not drawn");
}

#[test]
fn every_page_of_an_objects_note_is_prepared_for_local_drawing() {
    // Before: the picture/shape/text-box page and the picture page were refused
    // by the renderer admission, the empty page skipped (no image at all).
    let (snapshot, images) = fixture();
    let inventory = prepare::prepare_pages(&snapshot, None, false).unwrap();
    assert_eq!(inventory.iter().map(|p| p.index).collect::<Vec<_>>(), vec![0, 1, 2]);
    assert!(inventory.iter().all(|p| p.composite && !p.over_pdf));
    assert!(inventory[0].notice.is_some(), "foreign shape / odd line are approximate");
    assert_eq!(inventory[1].notice, None, "a picture page is exact");
    assert_eq!(inventory[2].notice, None, "an empty sheet is exact");
    let built = prepare::prepare_pages(&snapshot, None, true).unwrap();
    let body = |i: usize| rs_store::val::loads(std::str::from_utf8(&built[i].body).unwrap()).unwrap();
    assert!(built.iter().all(|p| is_composite(&p.body)));
    // Page 1: the picture first (z-order), then the shape; strokes and the
    // text box go to the renderer.
    let page1 = body(0);
    let Some(Val::List(items)) = page1.get("items") else { panic!() };
    let first = items[0].get("image").unwrap();
    assert!(images.contains_key(first.get("sha256").unwrap().as_str().unwrap()), "picture resolved by its file hash");
    let renderer = page1.get("renderer").and_then(Val::as_str).unwrap();
    assert!(renderer.contains("\"textBoxes\":[{\"at\":2,") && renderer.contains("\"text\":\"Kutu\""), "{renderer}");
    assert!(page1.get("rendererPlain").and_then(Val::as_str).is_some_and(|r| !r.contains("textBoxes")));
    // Page 3: blank sheet, no renderer.
    let page3 = body(2);
    assert_eq!(page3.get("renderer"), Some(&Val::Null));
    assert_eq!(page3.get("items"), Some(&Val::List(vec![])));
}

#[test]
fn notext_preserves_page_objects_and_other_text_boxes() {
    let (snapshot, _) = fixture();
    let page = prepare::notext_snapshot_page(&snapshot, 0).unwrap().unwrap();
    let body = rs_store::val::loads(std::str::from_utf8(&page.body).unwrap()).unwrap();
    let renderer = rs_store::val::loads(body.get("renderer").and_then(Val::as_str).unwrap()).unwrap();
    assert!(renderer.get("flow").is_none());
    assert!(renderer.get("textBoxes").is_some_and(Val::truthy));
    assert!(renderer.get("strokes").is_some_and(Val::truthy));
    assert!(body.get("items").is_some_and(Val::truthy));
}

