#[test]
fn pictures_are_fetched_verified_cached_and_drawn() {
    let dir = TempDir::new();
    let (_, images) = fixture();
    let asked = Arc::new(Mutex::new(Vec::new()));
    let env = TestEnv::new(Some(dir.path()), false);
    let (m, id) = manager_with(dir.path(), env, Some(media(images.clone(), asked.clone())), None);
    let manifest = m.manifest(&id).unwrap();
    let list = pages(&manifest);
    assert_eq!(list.len(), 3);
    // Page 2 has a Samsung canvas entry; pages 1 and 3 are local composites.
    for i in [0usize, 2] {
        assert_eq!(list[i].get("available"), Some(&Val::Bool(true)), "page {i}");
        assert_eq!(list[i].get("previewKind").and_then(Val::as_str), Some("page-reconstructed"));
    }
    assert_eq!(list[2].get("complete"), Some(&Val::Bool(true)));
    // Page 1's picture (red, frame 100,200-500,600) under the ink.
    let png = wait_png(&m, &id, 0);
    assert!(notes_preview::png_valid(&png, 1080, 1527));
    assert_eq!(pixel(&png, 300, 450), [230, 30, 30, 255]);
    assert_eq!(pixel(&png, 1000, 1500), [0xfc, 0xfc, 0xfc, 255], "page colour");
    assert!(asked.lock().unwrap().len() == 1);
    // The empty third page is a plain sheet.
    let blank = wait_png(&m, &id, 2);
    assert_eq!(pixel(&blank, 540, 760), [0xfc, 0xfc, 0xfc, 255]);
    m.close();
    m.join(Duration::from_secs(2));
    // A later session offline draws from the verified media cache only.
    for entry in std::fs::read_dir(dir.path().join("page-previews")).unwrap().flatten() {
        if entry.path().extension().is_some_and(|e| e == "png") {
            std::fs::remove_file(entry.path()).unwrap();
        }
    }
    let (offline, id) = manager_with(dir.path(), TestEnv::new(None, true), None, None);
    let again = wait_png(&offline, &id, 0);
    assert_eq!(pixel(&again, 300, 450), [230, 30, 30, 255]);
    offline.close();
    offline.join(Duration::from_secs(2));
}

#[test]
fn a_missing_picture_gives_a_calm_stand_in_until_it_can_be_fetched() {
    let dir = TempDir::new();
    let (_, images) = fixture();
    // Offline: the page is drawn at once with a placeholder for the picture.
    let (offline, id) = manager_with(dir.path(), TestEnv::new(None, true), None, None);
    let partial = wait_png(&offline, &id, 0);
    assert_eq!(pixel(&partial, 300, 450), [0xf1, 0xf1, 0xf1, 255], "placeholder, not an error");
    offline.close();
    offline.join(Duration::from_secs(2));
    // Connected later: the stand-in is served immediately and the full page
    // is drawn in the background.
    let asked = Arc::new(Mutex::new(Vec::new()));
    let (online, id) = manager_with(dir.path(), TestEnv::new(Some(dir.path()), false), Some(media(images, asked.clone())), None);
    assert_eq!(online.request(&id, 0, 0, 0.0).unwrap().as_deref(), Some(partial.as_slice()));
    assert!(online.wait_idle(Some(Duration::from_secs(120))));
    let full = wait_png(&online, &id, 0);
    assert_eq!(pixel(&full, 300, 450), [230, 30, 30, 255]);
    assert_eq!(asked.lock().unwrap().len(), 1);
    online.close();
    online.join(Duration::from_secs(2));
}

#[test]
fn a_canvas_page_whose_cache_cannot_be_used_is_drawn_locally() {
    // Before: the download/decoder error surfaced as "Sayfa görüntüsü açılamadı".
    let dir = TempDir::new();
    let (_, images) = fixture();
    let undecodable: Fetcher = Arc::new(|c: &CanvasPreviewCandidate, _: &dyn PreviewEnv, _: &dyn Fn() -> Result<(), Fail>| {
        assert_eq!(c.bind_number, "5");
        Ok(b"synthetic canvas cache".to_vec())
    });
    let asked = Arc::new(Mutex::new(Vec::new()));
    let (m, id) = manager_with(dir.path(), TestEnv::new(Some(dir.path()), false), Some(media(images, asked)), Some(undecodable));
    let list = pages(&m.manifest(&id).unwrap());
    assert_eq!(list[1].get("available"), Some(&Val::Bool(true)));
    assert_eq!(list[1].get("previewKind"), None, "still Samsung's canvas page in the manifest");
    let png = wait_png(&m, &id, 1);
    assert!(notes_preview::png_valid(&png, 1080, 1527));
    assert_eq!(pixel(&png, 300, 450), [0xf1, 0xf1, 0xf1, 255], "initial stand-in does not wait for media");
    assert!(m.wait_idle(Some(Duration::from_secs(30))));
    let completed = wait_png(&m, &id, 1);
    assert_eq!(pixel(&completed, 300, 450), [30, 60, 230, 255], "background fills the page's picture");
    m.close();
    m.join(Duration::from_secs(2));
}

#[test]
fn text_box_page_renders_when_the_renderer_is_built() {
    let (snapshot, _) = fixture();
    let native = notes_preview::NativeInk::new(notes_preview::env::default_project_root(), None);
    if !native.renderer().is_file() {
        eprintln!("ink renderer not built; skipping render");
        return;
    }
    use notes_preview::InkBackend;
    let (png, complete) = native.render_page(&snapshot, 0, &|_| None).unwrap();
    assert!(notes_preview::png_valid(&png, 1080, 1527));
    assert!(!complete, "picture not supplied: placeholder");
    // Text box frame 50,1000-400,1100: the outlined "Kutu" glyphs are dark.
    let dark = (60..300).flat_map(|x| (1000..1100).map(move |y| (x, y))).any(|(x, y)| pixel(&png, x, y)[0] < 128);
    assert!(dark, "text box text drawn");
}

