#[test]
fn ink_tiles_never_replace_samsung_canvas_cache() {
    let dir = TempDir::new();
    let (manager, id) = manager_with(dir.path(), TestEnv::new(None, true), None, None);
    let revision = manager.source(&id).unwrap().0[4].as_i64().unwrap();
    assert!(matches!(manager.entry(&id).unwrap().candidates.get(&1), Some(notes_preview::Candidate::Canvas(_))));
    let error = manager.ink_layer(&id, 1, revision, None, None).unwrap_err();
    assert_eq!((error.code.as_str(), error.status), ("preview_unavailable", 404));
    manager.close();manager.join(Duration::from_secs(2));
}

/// `tests/fixtures/floating_note.json` (generated by `cargo test -p
/// notes-host --test ink_objects -- --ignored regen_preview_floating_fixture`):
/// the objects note plus a free-floating green picture on page 3 that the
/// body text anchors with an `objectSpan` (structure of a phone test note).
fn floating_fixture() -> (Val, BTreeMap<String, Vec<u8>>) {
    let text = std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/floating_note.json")).unwrap();
    let value = rs_store::val::loads(&text).unwrap();
    let Some(Val::Dict(images)) = value.get("images").cloned() else { panic!() };
    let images = images.into_iter().map(|(k, v)| (k, rs_editor::pyval::b64decode_strict(v.as_str().unwrap()).unwrap())).collect();
    (value.get("snapshot").unwrap().clone(), images)
}

#[test]
fn a_free_floating_picture_is_drawn_on_its_page() {
    // Before: the whole note was refused ("Bu not eklenmiş nesneler taşıyor.")
    // and the text anchor (`objectSpan`) failed the body reading too.
    let (snapshot, images) = floating_fixture();
    let inventory = prepare::prepare_pages(&snapshot, None, false).unwrap();
    assert_eq!(inventory.iter().map(|p| p.index).collect::<Vec<_>>(), vec![0, 1, 2]);
    assert_eq!(inventory[2].notice, None, "the picture is placed by its own frame");
    let built = prepare::prepare_pages(&snapshot, Some(2), true).unwrap();
    let body = rs_store::val::loads(std::str::from_utf8(&built[0].body).unwrap()).unwrap();
    let Some(Val::List(items)) = body.get("items") else { panic!() };
    assert_eq!(items.len(), 1, "{items:?}");
    let sha = items[0].get("image").and_then(|i| i.get("sha256")).and_then(Val::as_str).unwrap().to_string();
    assert!(images.contains_key(&sha));
    assert_eq!(body.get("renderer"), Some(&Val::Null), "the anchor placeholder is not laid out as text");
    // Drawn through the manager with the picture fetched by its file hash.
    let dir = TempDir::new();
    let s = store(dir.path());
    let id = note_with_document(&s, &snapshot);
    let asked = Arc::new(Mutex::new(Vec::new()));
    let options = PreviewOptions { media_fetcher: Some(media(images, asked.clone())), ..Default::default() };
    let m = Arc::new(PreviewManager::with_options(s, TestEnv::new(Some(dir.path()), false), options).unwrap());
    let list = pages(&m.manifest(&id).unwrap());
    assert_eq!(list[2].get("available"), Some(&Val::Bool(true)));
    assert_eq!(list[2].get("complete"), Some(&Val::Bool(true)));
    let png = wait_png(&m, &id, 2);
    assert_eq!(pixel(&png, 300, 400), [20, 160, 60, 255], "the floating picture inside its frame");
    assert_eq!(pixel(&png, 700, 1000), [0xfc, 0xfc, 0xfc, 255], "page colour outside it");
    assert_eq!(asked.lock().unwrap().as_slice(), [sha]);
    m.close();
    m.join(Duration::from_secs(2));
}

#[test]
fn deterministic_canvas_decode_failure_is_not_retried_for_same_content() {
    use std::sync::atomic::{AtomicUsize, Ordering};
    let dir = TempDir::new();
    let store = store(dir.path());
    let (snapshot, images) = fixture();
    let id = note_with_document(&store, &snapshot);
    let calls = Arc::new(AtomicUsize::new(0));
    let count = calls.clone();
    let manager = PreviewManager::with_options(store, TestEnv::new(Some(dir.path()), false), PreviewOptions {
        fetcher: Some(Arc::new(move |_, _, _| { count.fetch_add(1, Ordering::SeqCst); Ok(b"undecodable".to_vec()) })),
        decoder: Some(Arc::new(|_, _| Err(Fail::new(notes_preview::Kind::Preview, "invalid cache")))),
        media_fetcher: Some(media(images, Arc::new(Mutex::new(Vec::new())))),
        ..Default::default()
    }).unwrap();
    wait_png(&manager, &id, 1);
    assert!(manager.wait_idle(Some(Duration::from_secs(30))));
    let candidate = manager.entry(&id).unwrap().candidates[&1].clone();
    let path = manager.path(&candidate).unwrap().with_extension("local.png");
    std::fs::remove_file(path).unwrap();
    wait_png(&manager, &id, 1);
    assert_eq!(calls.load(Ordering::SeqCst), 1);
    manager.close();
}

#[test]
fn same_revision_snapshot_replacement_invalidates_note_inventory() {
    use rs_store::db::Sql;
    let dir = TempDir::new();
    let store = store(dir.path());
    let (old, _) = fixture();
    let text = std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/floating_note.json")).unwrap();
    let floating = rs_store::val::loads(&text).unwrap();
    let new = floating.get("snapshot").unwrap();
    let id = note_with_document(&store, &old);
    let manager = PreviewManager::new(store.clone(), TestEnv::new(None, true)).unwrap();
    let before = manager.entry(&id).unwrap();
    assert_eq!(before.pages.len(), 3);
    let source = manager.source(&id).unwrap();
    let json = rs_store::val::dumps(new, true, true).unwrap();
    store.with_db(|db| { db.exec("UPDATE notes SET base_document=? WHERE id=?", &rs_store::p![json, id.as_str()])?; Ok(()) }).unwrap();
    assert_eq!(manager.source(&id).unwrap().0, source.0);
    let after = manager.entry(&id).unwrap();
    assert_ne!(after.candidates, before.candidates);
    manager.close();
}

#[test]
fn foreground_canvas_returns_local_before_blocked_download_and_upgrades() {
    use std::sync::mpsc;
    let dir = TempDir::new();
    let store = store(dir.path());
    let (snapshot, images) = fixture();
    let id = note_with_document(&store, &snapshot);
    let (entered_tx, entered_rx) = mpsc::channel();
    let (release_tx, release_rx) = mpsc::channel();
    let release_rx = Mutex::new(release_rx);
    let expected = png(1080, 1527, &vec![255; 1080 * 1527 * 4]);
    let full = expected.clone();
    let manager = PreviewManager::with_options(store, TestEnv::new(Some(dir.path()), false), PreviewOptions {
        fetcher: Some(Arc::new(move |_, _, _| {
            entered_tx.send(()).unwrap();
            release_rx.lock().unwrap().recv_timeout(Duration::from_secs(15)).unwrap();
            Ok(b"synthetic".to_vec())
        })),
        decoder: Some(Arc::new(move |_, _| Ok(full.clone()))),
        media_fetcher: Some(media(images, Arc::new(Mutex::new(Vec::new())))),
        ..Default::default()
    }).unwrap();
    let standin = manager.request(&id, 1, 0, 8.0).unwrap().expect("foreground must not wait for download");
    assert_ne!(standin, expected);
    entered_rx.recv_timeout(Duration::from_secs(5)).expect("full image should start in background");
    assert_eq!(manager.request(&id, 1, 0, 0.0).unwrap(), Some(standin));
    release_tx.send(()).unwrap();
    assert!(manager.wait_idle(Some(Duration::from_secs(20))));
    assert_eq!(manager.request(&id, 1, 0, 5.0).unwrap(), Some(expected));
    manager.close();
}

#[test]
fn forbidden_canvas_is_not_retried_after_a_new_standin() {
    use std::sync::atomic::{AtomicUsize, Ordering};
    let dir = TempDir::new();
    let store = store(dir.path());
    let (snapshot, images) = fixture();
    let id = note_with_document(&store, &snapshot);
    let env = TestEnv::new(Some(dir.path()), false);
    let calls = Arc::new(AtomicUsize::new(0));
    let count = calls.clone();
    *env.http.lock().unwrap() = Some(Box::new(move |_, _| { count.fetch_add(1, Ordering::SeqCst); Ok((403, vec![], None)) }));
    let manager = PreviewManager::with_options(store, env, PreviewOptions {
        media_fetcher: Some(media(images, Arc::new(Mutex::new(Vec::new())))), ..Default::default()
    }).unwrap();
    wait_png(&manager, &id, 1);
    assert!(manager.wait_idle(Some(Duration::from_secs(30))));
    assert_eq!(calls.load(Ordering::SeqCst), 1);
    let path = manager.path(&manager.entry(&id).unwrap().candidates[&1]).unwrap().with_extension("local.png");
    std::fs::remove_file(path).unwrap();
    wait_png(&manager, &id, 1);
    assert!(manager.wait_idle(Some(Duration::from_secs(30))));
    assert_eq!(calls.load(Ordering::SeqCst), 1, "403 must not trigger another download for the same URL");
    manager.close();
}
